```python
def eulerian_num(n, m):
    # Define a helper function to calculate the binomial coefficient
    def binomial_coefficient(k, j):
        if j == 0 or j == k:
            return 1
        if k < j:
            return 0
        if j == 1 or j == k - 1:
            return k
        if j > 1 and j < k - 1:
            return binomial_coefficient(k - 1, j - 1) + (k - 1) * binomial_coefficient(k - 1, j)

    if m == 0 or m > n:
        return 0
    if m == 1:
        return 1
    if m == 2:
        return n - 1
    if n == m:
        return 1

    # Use the recursive formula to calculate the Eulerian number
    return (n - m) * (2 * (n - 1) - m) * eulerian_num(n - 1, m - 1) + m * eulerian_num(n - 1, m)

